func novelParseSince(s string, now time.Time) (time.Time, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return now.Add(-7 * 24 * time.Hour), nil
	}
	if d, err := cliutil.ParseDurationLoose(s); err == nil {
		return now.Add(-d), nil
	}
	for _, layout := range []string{"2006-01-02", time.RFC3339, time.RFC3339Nano} {
		if t, err := time.Parse(layout, s); err == nil {
			return t, nil
		}
	}
	return time.Time{}, fmt.Errorf("expected date or duration")
}

func novelRenderDigestMarkdown(w io.Writer, view novelDigestView) error {
	for _, group := range view.Groups {
		header := group.Source
		if group.Author != "" {
			header += " — " + group.Author
		}
		if _, err := fmt.Fprintf(w, "## %s\n\n", header); err != nil {
			return err
		}
		for _, h := range group.Highlights {
			if _, err := fmt.Fprintf(w, "- %s", h.Text); err != nil {
				return err
			}
			if h.Note != "" {
				if _, err := fmt.Fprintf(w, "\n  - Note: %s", h.Note); err != nil {
					return err
				}
			}
			if _, err := fmt.Fprint(w, "\n"); err != nil {
				return err
			}
		}
		if _, err := fmt.Fprint(w, "\n"); err != nil {
			return err
		}
	}
	if view.Note != "" && len(view.Groups) == 0 {
		_, err := fmt.Fprintln(w, view.Note)
		return err
	}
	return nil
}

func novelDigestReport(cmd *cobra.Command, since time.Time, categories map[string]bool) (novelDigestView, error) {
	view := novelDigestView{Since: since.Format(time.RFC3339), Groups: make([]novelDigestGroup, 0)}
	exists, err := novelLocalStoreExists(cmd)
	if err != nil {
		return view, err
	}
	if !exists {
		view.Note = novelMissingLocalDataNote
		return view, nil
	}
	db, err := novelOpenStore(cmd)
	if err != nil {
		return novelDigestView{}, err
	}
	defer db.Close()
	count, err := novelTableCount(db, "highlights")
	if err != nil {
		return view, fmt.Errorf("count highlights: %w", err)
	}
	if count == 0 {
		view.Note = "No synced highlights found. Run 'readwise-pp-cli sync' first."
		return view, nil
	}
	rows, err := db.DB().Query(`SELECT h.text, h.note, COALESCE(NULLIF(h.highlighted_at,''), h.created_at), b.title, b.author, b.category
		FROM highlights h
		LEFT JOIN books b ON CAST(b.id AS TEXT) = CAST(h.book_id AS TEXT)
		WHERE julianday(COALESCE(NULLIF(h.highlighted_at,''), h.created_at)) >= julianday(?)
		ORDER BY julianday(COALESCE(NULLIF(h.highlighted_at,''), h.created_at)) DESC`, since.Format(time.RFC3339))
	if err != nil {
		return view, err
	}
	defer rows.Close()
	groups := map[string]*novelDigestGroup{}
	order := make([]string, 0)
	for rows.Next() {
		var text, note, highlighted, title, author, category sql.NullString
		if err := rows.Scan(&text, &note, &highlighted, &title, &author, &category); err != nil {
			return view, err
		}
		if len(categories) > 0 && !categories[strings.ToLower(category.String)] {
			continue
		}
		source := cliutil.CleanText(title.String)
		if source == "" {
			source = "Untitled"
		}
		key := source + "\x00" + author.String
		group := groups[key]
		if group == nil {
			group = &novelDigestGroup{Source: source, Author: cliutil.CleanText(author.String), Category: category.String, Highlights: make([]novelDigestHighlight, 0)}
			groups[key] = group
			order = append(order, key)
		}
		group.Highlights = append(group.Highlights, novelDigestHighlight{Text: cliutil.CleanText(text.String), Note: cliutil.CleanText(note.String), HighlightedAt: highlighted.String})
		view.Count++
	}
	if err := rows.Err(); err != nil {
		return view, err
	}
	sort.Strings(order)
	for _, key := range order {
		view.Groups = append(view.Groups, *groups[key])
	}
	return view, nil
}

